<script id="v087-main-attribute-runtime-fix">
function v087FixMainAttributeBadge(){
  const candidates=[...document.querySelectorAll('*')].filter(el =>
    el.children.length===0 &&
    (el.textContent||'').trim().toUpperCase()==='HAUPTATTRIBUT'
  );
  candidates.forEach(badge=>{
    badge.style.position='absolute';
    badge.style.right='92px';
    badge.style.top='8px';
    badge.style.zIndex='2';
    badge.style.whiteSpace='nowrap';
    badge.style.pointerEvents='none';

    const row=badge.closest('.stat-row') || badge.parentElement;
    if(row && getComputedStyle(row).position==='static') row.style.position='relative';
  });
}

const v087BaseRender=render;
render=function(){
  v087BaseRender();

  requestAnimationFrame(v087FixMainAttributeBadge);
};

try{
  v087FixMainAttributeBadge();
  render();
}catch(e){console.error('V4.02 main attribute fix',e);}
</script>


